.pop{background:url(snowbg.png) center top/cover no-repeat #dff2ff!important}

/* 色を4色にしぼる：紺・白・赤・黄 */
.c1 .hd,.c2 .hd,.c5 .hd,.c3 .lg,.c4 .lg{background:#1b2550!important}
.hd .no,.lg .no{background:#ffd23a!important}
.two .a,.two .b{background:#fff!important}
.c3 .hit span,.c4 .hit span{background:#fff!important;color:#1b2550!important}
.c4 .hit span{color:#1b2550!important}
.c3 .ls li:before,.c4 .ls li:before{color:#e8442c!important}
.pass b{color:#e8442c!important}
.rk:nth-of-type(1) b,.rk:nth-of-type(2) b,.rk:nth-of-type(3) b{background:#ffd23a!important}
.title .f{color:#fff!important}
.tag{background:#ffd23a!important}

/* 強弱：大事な所は大きく、説明は小さく */
.c1 .lead{font-size:30px!important}.c1 .lead .big{font-size:60px!important}
.two b{font-size:60px!important}.two small{font-size:20px!important}.two span{font-size:20px!important}
.c1 .note{font-size:16px!important;margin-top:4px}
.blk p{font-size:18px!important}.blk .tk{font-size:58px!important}.blk .tk small{font-size:34px!important}
.c2 .note{font-size:15.5px!important}
