.pass{white-space:nowrap}
.pass b{font-size:36px!important}
.pass span{font-size:17px!important}

/* 枠ごとの主役 */
.blk .tk3{font-size:38px!important}.blk .tk3 small{font-size:24px!important}
.free-s{font-size:30px!important;margin-bottom:2px}
.hero4{text-align:center;font-weight:900;font-size:36px;line-height:1.2;color:#fff;background:#e8442c;border:4px solid #1b2550;border-radius:22px;padding:8px 6px 10px;margin:4px 0 8px}
.rk1{padding:4px 0 8px!important}
.rk1 b{width:44px!important;height:44px!important;font:900 26px/38px "Arial Black"!important}
.rk1 .h1{font-size:40px;font-weight:900;color:#e8442c}
.rk1 .h1s{font-size:20px}
.pass b{font-size:28px!important}
.pass span{font-size:16px!important}
.pass{font-size:18px!important}

.c3 .hit span,.c4 .hit span{font-size:22px!important;padding:1px 14px!important}
.hit .big{font-size:26px!important}
.first span{font-size:22px!important}
.hero4{font-size:33px!important;padding:6px 6px 8px!important;margin:4px 0 4px!important}
