/* 上野 */
.hh{position:absolute;left:18px;width:1019px;top:256px;height:62px;background:#1b2550;border:4px solid #1b2550;border-radius:20px;box-shadow:4px 4px 0 #1b2550;display:flex;align-items:center;gap:18px;padding:0 22px;color:#fff}
.hh .nm{flex:none;font:italic 900 32px "Arial Black",sans-serif;color:#ffd23a}
.hh p{font-weight:900;font-size:25px;white-space:nowrap}
.hh p b{color:#ffd23a;font-size:32px}
.hh small{font-size:15px;font-weight:700;color:#cfd6ee;margin-left:10px}
.u1 .lead{text-align:center;font-weight:900;font-size:32px;margin-top:4px}
.u1 .lead b{color:#e8442c;font-size:44px}
.u1 .hero{text-align:center;font-weight:900;font-size:96px;color:#e8442c;line-height:1;letter-spacing:-2px}
.u1 .hero small{font-size:44px}
.u1 .cond{margin-top:8px}
.cond li{list-style:none;font-size:16.5px;font-weight:700;color:#3a4470;line-height:1.3;padding:3px 0 3px 20px;position:relative;border-bottom:2px dotted #c9cfe0}
.cond li:before{content:"●";position:absolute;left:2px;top:5px;font-size:11px;color:#e8442c}
.u2 .tk small{font-size:26px!important}
.u2 .row{display:flex;align-items:flex-end;gap:12px}
.u2 .row .mx{border-left:3px dotted #c9cfe0;padding-left:12px;font-size:18px;font-weight:800}
.u2 .row .mx b{display:block;font-size:34px;font-weight:900;color:#e8442c;line-height:1.1}
.u2 .row .mx b small{font-size:20px}
.u1 .hero{font-size:84px!important}.u1 .lead{font-size:28px!important;margin-top:0!important}
.c5 .rk1 .h1{font-size:34px}.c5 .rk{font-size:22px!important;padding:3px 0!important}
.pass2 b{font-size:30px!important}.c5 .rk1{padding:2px 0 4px!important}.c5 .bd{padding-top:6px!important}
.c5 .rk{padding:2px 0!important}.c5 .rk1 .h1{font-size:32px!important}.pass2{display:flex;align-items:center;gap:10px;margin-top:4px!important}
.pass2{margin-top:6px;font-size:18px;font-weight:800}
.pass2 b{display:block;font-size:34px;font-weight:900;color:#e8442c;line-height:1.15}

